import Mathlib

open MeasureTheory

universe u v w

theorem iso_lemma2 : ∀ {α : Type u} {β : Type v} {γ : Type w}
    {mα : MeasurableSpace α} [MeasurableSpace β] [MeasurableSpace γ]
    {f : α → β} {g : β → γ},
      @Measurable α β mα inferInstance f →
        Measurable g →
        @Measurable α γ mα inferInstance (g ∘ f) := by
  exact?
